/* Saeparan 1.4 */
body:not(#layout) [hidden]{display:none!important}
.related-posts,.portal-lead{display:none}.related-posts.show,.portal-lead.show{display:block}
:root{--teal:#00a7ac;--accent:#00858a;--green:#00c99a;--red:#e5224c;--bg:#eee;--paper:#fff;--ink:#151515;--muted:#777;--line:#e9e9e9;--width:1024px}
