x 16px;margin:24px 0}.video-panel .section-head{padding-left:0;border:0}.video-panel .section-head:before{display:none}.video-panel .section-head a{color:#fff}.video-strip{display:grid;grid-auto-flow:column;grid-auto-columns:calc((100% - 48px)/4);gap:16px;overflow:auto;scrollbar-width:thin;padding-bottom:12px}.video-card{position:relative;display:block;border-radius:6px;overflow:hidden;background:#333;aspect-ratio:9/15}.video-card>img{width:100%;height:100%;object-fit:cover}.video-card:after{content:'';position:absolute;inset:40% 0 0;background:linear-gradient(transparent,#000e)}.video-card .video-copy{position:absolute;bottom:0;padding:12px;z-index:1}.video-copy h3{font-size:15px;line-height:1.4}.video-copy small{font-size:11px}.video-card .play-mark{width:36px;height:36px;font-size:16px;border-radius:50%;top:35%}.duo{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:24px 0}.duo .panel{margin:0}.duo .section-head{background:#00427e;color:#fff}.duo>div:nth-child(2) .section-head{background:#008b70}.duo .section-head:before{display:none}.duo .section-head a{color:white}.duo .news-row{margin:0 14px}.duo .news-row img{width:90px;height:65px}.feed-list{padding:0 16px}.feed-list .news-row img{width:180px;height:120px}.feed-list .news-row h3{font-size:20px;line-height:1.35}.feed-list .snippet{font-size:14px;color:#777;margin-top:8px}.grid-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;padding:16px}.grid-card img{width:100%;aspect-ratio:16/10;object-fit:cover;border-radius:4px}.grid-card h3{font-size:18px;line-height:1.4;margin-top:10px}.load-more{display:block;text-align:center;margin:16px auto;border:1px solid var(--accent);border-radius:3px;color:var(--accent);background:var(--paper);padding:9px 28px;font-size:14px}.empty-state{padding:24px;color:var(--muted);font-size:14px}.home-only{display:none}.is-home .home-only{display:block}.is-home .home-only.duo{display:grid}.enhanced-home .native-posts{display:none}.article-view{background:var(--paper