.comment{padding:15px 0;border-bottom:1px solid var(--line)}.comment-body{margin-top:8px}.native-card{background:var(--paper);border-bottom:1px solid var(--line);padding:20px}.native-card h2{font-size:24px;margin-bottom:8px}.native-card img{width:180px;aspect-ratio:16/10;object-fit:cover;float:right;margin:0 0 10px 16px}.native-card:after{content:'';display:block;clear:both}.page-title{font-size:36px;text-align:center;margin:20px 0 28px}.pager{display:flex;gap:12px;justify-content:center;margin:24px 0}.pager a{padding:9px 20px;background:var(--paper);border:1px solid var(--line);border-radius:3px;font-size:14px}.site-footer{background:#e5e5e5;margin-top:36px;padding:36px 0 18px;color:#666}.footer-inner{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:36px;font-size:13px}.footer-inner h3{color:var(--ink);font-size:15px;margin-bottom:12px}.footer-links{display:grid;grid-template-columns:1fr 1fr;gap:8px}.footer-about p{margin-top:18px;max-width:310px}.copyright{border-top:1px solid #ccc;margin-top:28px;padding-top:15px;font-size:11px;display:flex;justify-content:space-between}.back-top{position:fixed;bottom:20px;right:20px;background:var(--accent);border:0;color:#fff;width:36px;height:36px;border-radius:50%;z-index:20}.mobile-bottom{display:none}.error-panel{padding:40px;text-align:center;background:var(--paper)}
.dark{--bg:#17191a;--paper:#242728;--ink:#eee;--muted:#a8a8a8;--line:#373b3c}.dark .search-form input,.dark .sub-nav a,.dark .article-tags a{background:#343838;color:#ddd}.dark .ad-placeholder{background:#252929;border-color:#303535;color:#aaa}.dark .site-footer{background:#202526}.dark .logo small{color:#aaa}.dark .post-body blockquote{background:#293b3c}.dark .news-row .byline{color:#bbb}
body#layout{background:#fff}body#layout .site-header,body#layout .side-ad{position:static!important;width:auto!important}body#layout .wrap{width:100%!important}body#layout .home-only,body#layout .config-data,body#layout .native-posts{display:block!important}body#layout .lead-layout,body#layout .content-layout,body#layout .duo{display:block!important}body#layout .section{border:1px dashed #aaa;padding:10px;margin:8px}body#layout .header-actions,body#layout .mobile-bottom{display:none!important}body#layout .ad-placeholder{min-height:40px;height:auto}body#layout .header-top{height:auto;display:block}body#layout .widget{min-height:35px}
@media(min-width:701px) and (max-width:1050px){.main-nav{gap:16px;overflow-x:auto}.main-nav .more-menu{display:none}.header-top{gap:24px}.header-actions{gap:16px}.search-form{width:260px}.header-actions .write-link{display:none}}
@media(max-width:1360px){.side-ad{display:none}}
