px;padding:0 12px 12px;border-radius:0}.video-strip{grid-auto-columns:44%;gap:10px}.duo{grid-template-columns:1fr;margin:20px 0}.is-home .home-only.duo{display:grid}.grid-cards{grid-template-columns:1fr 1fr;gap:12px;padding:12px}.grid-card h3{font-size:15px}.feed-list{padding:0 12px}.feed-list .news-row img{width:105px;height:85px}.feed-list .news-row h3{font-size:17px}.feed-list .snippet{display:none}.content-layout>aside{display:none}.article-layout>aside{display:none}.article{padding:0 4px}.breadcrumb{margin:10px 0 25px;font-size:12px}.article h1{font-size:27px;line-height:1.3;margin-bottom:22px}.article-meta{font-size:12px}.post-body{font-size:18px;line-height:1.65}.post-body p{margin-bottom:22px}.article-view .main-wrap{padding-top:16px}.page-title{font-size:28px;margin:12px 0 20px}.native-card{padding:16px}.native-card h2{font-size:20px}.native-card img{width:105px}.footer-inner{grid-template-columns:1fr;gap:24px}.copyright{display:block;line-height:2}.site-footer{padding-bottom:80px}.mobile-bottom{display:flex;position:fixed;bottom:0;left:0;right:0;z-index:45;height:57px;background:var(--paper);border-top:1px solid var(--line);justify-content:space-around;align-items:center}.mobile-bottom a{display:flex;flex-direction:column;align-items:center;gap:2px;font-size:10px;color:var(--muted)}.mobile-bottom a:first-child{color:var(--accent)}.mobile-bottom svg{width:21px;height:21px}.back-top{bottom:72px;right:14px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}

.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}

.post-body figure{margin:0 0 24px}

.header-top>#Brand{display:none}.feed-block>.section{margin:0}.ad-slot>.section{margin:0}

#primary-links{display:contents}.site-brand-slot{flex:0 0 auto}.ad-slot iframe{max-width:100%}.static-page .article-meta,.static-page .article-author{display:none}


/* SaeMag original SVG ring icons, shared by all article share bars. */
.sae-social-library{position:absolute;width:0;height:0;overflow:hidden;pointer-events:none}
.share-bar{gap:8px;flex-wrap:wrap}
.share-bar .sae-share-link{width:44px;height:44px;border:0;background:transparent;color:var(--ink);margin:0}
.sae-social-icon{width:36px;height:36px;stroke:none;fill:none}
.share-bar .sae-copy{width:auto;min-height:40px;height:auto;gap:7px;border-radius:24px;padding:8px 12px;color:var(--ink);font-size:13px}
.sae-copy svg{width:18px;height:18px;flex-shrink:0}
.sae-share-link:hover{opacity:.75}
.sm-ad{text-align:center;line-height:0}.sm-ad .widget-content{line-height:normal}
.sm-ph{display:flex;align-items:center;justify-content:center;margin:auto;max-width:100%;border:1px dashed var(--line);color:var(--muted);font:13px/1.3 Heebo,Arial,sans-serif;text-align:center;background:repeating-linear-gradient(45deg,#8881,#8881 10px,transparent 10px,transparent 20px)}
.sm-vt{display:none;background:#000;position:relative}
.sm-vt-bar{display:flex;align-items:center;justify-content:center;height:26px;color:#fff;font-size:11px;letter-spacing:.3px;position:relative;z-index:3;background:#000}
.sm-vt-bar .sm-x{position:absolute;top:1px;right:8px;width:22px;height:22px;border:0;border-radius:50%;background:#333;color:#fff;padding:0;line-height:1}
.sm-px{position:relative;clip-path:inset(0 0 0 0);overflow:hidden}
.sm-vt .sm-px{height:330px}.sm-vt .sm-px-in{top:191px}
.sm-px-in{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);width:max-content;max-width:calc(100vw - 24px)}
.sm-vt .sm-ph{width:325px;height:300px;background-color:#111;color:#bbb;border-color:#333}
.sm-adpx{margin:24px 0;clear:both}.post-body>.sm-adpx{margin:24px 0}
.sm-adpx .sm-px{height:630px;background:#8881}
.sm-adpx .sm-ph{width:300px;height:600px;background-color:var(--paper)}
@media(max-width:991px){.sm-vt{display:block}.sm-vt.closed{display:none}}
@media(max-width:600px){.sm-adpx .sm-px{height:520px}}

.tbd-license-gate[hidden],.tbd-license-shield[hidden],.tbd-license-status[hidden],#tbd-license-context[hidden]{display:none!important}
.tbd-license-gate,.tbd-license-gate *,.tbd-license-status,.tbd-license-status *{box-sizing:border-box}
.tbd-license-gate{position:fixed;inset:0;z-index:2147483000;display:grid;place-items:center;overflow:auto;padding:24px 16px;background:rgba(15,23,42,.55);font-family:Arial,system-ui,sans-serif;color:#172339;text-align:left;line-height:1.6}
.tbd-license-card{width:100%;max-width:460px;margin:auto;padding:30px;background:#fff;border:1px solid #e5eaf2;border-radius:22px;box-shadow:0 24px 80px #0f172a40}
.tbd-license-brand{display:inline-flex;align-items:center;gap:8px;color:#172339!important;text-decoration:none!important;font:bold 21px/1.3 Arial,sans-serif;letter-spacing:-.6px}
.tbd-license-brand b{color:#2456d9}.tbd-license-logo{position:relative;display:grid;place-items:center;width:30px;height:30px;border-radius:9px;color:#fff;background:#2456d9;font:bold 24px/1 Arial,sans-serif;letter-spacing:0}.tbd-license-logo>span{position:absolute;right:5px;bottom:5px;width:6px;height:6px;border-radius:50%;background:#ffb300}
.tbd-license-symbol{display:grid;place-items:center;width:54px;height:54px;margin-top:28px;margin-bottom:16px;border-radius:15px;background:#edf2ff;color:#2456d9}
.tbd-license-eyebrow{margin:0 0 8px!important;color:#526178;font:bold 11px/1.5 Arial,sans-serif;letter-spacing:1.3px}
.tbd-license-card h2{margin:0 0 14px!important;padding:0;color:#172339;font:bold 26px/1.25 Arial,sans-serif;letter-spacing:-.7px;overflow-wrap:anywhere}
.tbd-license-card #tbd-license-description{margin:0 0 24px!important;color:#526178;font:15px/1.7 Arial,sans-serif;overflow-wrap:anywhere}
.tbd-license-card strong{color:#172339;font-weight:700}
.tbd-license-actions{display:grid;gap:10px}
.tbd-license-actions a{display:flex;justify-content:center;align-items:center;min-height:48px;padding:12px 16px;border:1px solid #2456d9;border-radius:11px;background:#2456d9;color:#fff!important;text-decoration:none!important;font:bold 15px/1.45 Arial,sans-serif;text-align:center;overflow-wrap:anywhere}
.tbd-license-actions a:hover{background:#173fa9;border-color:#173fa9}.tbd-license-actions .tbd-license-secondary{background:#fff;color:#2456d9!important;border-color:#d3ddef}.tbd-license-actions .tbd-license-secondary:hover{background:#f5f7fb}
#tbd-license-check{display:block;margin:18px auto 0;padding:6px 3px;border:0;background:transparent;color:#526178;font:14px/1.5 Arial,sans-serif;text-align:center;text-decoration:underline;text-underline-offset:4px;cursor:pointer}
.tbd-license-gate :focus-visible,.tbd-license-status button:focus-visible{outline:3px solid #9db5ff;outline-offset:3px}
.tbd-license-modal{overflow:hidden}.tbd-license-shield{position:fixed;inset:0;z-index:2147482000;background:transparent}
.tbd-license-status{position:fixed;z-index:2147483001;left:50%;bottom:18px;transform:translateX(-50%);width:calc(100% - 32px);max-width:440px;padding:16px 18px;border:1px solid #e5eaf2;border-radius:12px;background:#fff;color:#526178;box-shadow:0 6px 30px #0f172a20;font:14px/1.6 Arial,sans-serif}
.tbd-license-status button{display:block;margin-top:8px;padding:7px 12px;border:0;border-radius:8px;background:#2456d9;color:#fff;font:bold 13px/1.5 Arial,sans-serif;cursor:pointer}
@media(max-width:380px){.tbd-license-card{padding:24px 20px}.tbd-license-card h2{font-size:23px}}


/* tb-identity-presentation-b-20261107 */
[data-tb-logo-mirror] img{display:block;width:auto;max-width:100%;height:auto;max-height:48px;object-fit:contain} .tb-identity-wordmark{font:700 28px/1.2 Arial,sans-serif;white-space:nowrap}
#brand-name img{display:block;width:auto;height:auto;max-width:170px;max-height:48px;object-fit:contain}.footer-about [data-tb-logo-mirror] img{max-width:190px;max-height:52px}@media(max-width:700px){#brand-name img{max-width:155px;max-height:42px}}

/* Native license input is invisible on the public site. */
.tb-license-settings{display:none!important}

head.b:template-skin:
/* TemaBlogger License Key: native Layout controls remain editable. */
body#layout .tb-license-settings{display:block!important;width:auto!important;clear:both!important;margin:0 0 16px!important;padding:12px!important;border:1px solid #d8e3f5!important;border-radius:12px!important;background:#f0f5ff!important}
body#layout .tb-license-settings .add_widget{display:none!important}
body#layout .section{display:block;border:1px dashed #aaa;margin:8px;padding:8px}body#layout .side-ad{position:static}
body#layout .site-header,body#layout .wrap,body#layout .home-only,body#layout .portal-lead,body#layout .related-posts,body#layout .native-posts,body#layout .lead-layout,body#layout .content-layout,body#layout .duo,body#layout .side-ad,body#layout .feed-block,body#layout .header-top,body#layout #Brand{display:block!important;position:static!important;width:auto!important;height:auto!important;overflow:visible!important}
body#layout .section{min-height:90px!important}
body#layout .widget{display:block!important;visibility:visible!important;min-height:60px}
body#layout .block-output,body#layout .ad-placeholder,body#layout .logo,body#layout .search-form{display:none!important}

body#layout .sm-vt,body#layout .sm-adhold{display:block!important;position:static!important;width:auto!important}
body#layout .sm-px,body#layout .sm-px-in{position:static!important;transform:none!important;clip-path:none!important;overflow:visible!important;width:auto!important;max-width:none!important;height:auto!important}
body#layout .sm-ph,body#layout .sm-vt-bar,body#layout .sae-social-library{display:none!important}

b:if.script:
//
/* tb-identity-presentation-b-20261107: native logo and exact stock credit presentation only. */
(function(){
 'use strict';
 var cfg={"slug":"saeparan","kind":"customer","source":"#brand-name","native":false,"mirror":"[data-tb-logo-mirror=\"saeparan\"]","creditTargets":""};
 var queued=false;
 function tidy(s){return String(s||'').replace(/\s+/g,' ').trim();}
 function stockCredit(el){
  var text=tidy(el.textContent),links=el.querySelectorAll('a');
  var linked=/^Copyright © (\d{4})(?:\.)? Tema Blogger(?: \.)?\.?(?: )All rights reserved\.$/.exec(text);
  var year=linked&&linked[1];
  if(linked){
   if(links.length!==1||tidy(links[0].textContent)!=='Tema Blogger'||links[0].getAttribute('href')!=="https://www.temablogger.com/")return;
  }else{
   var legacy=cfg.slug==='saetimes'&&cfg.kind==='demo'&&/^© (\d{4}) SAETIMES\. All Right Reserved\.$/.exec(text);
   if(!legacy||links.length!==0)return;year=legacy[1];
  }
  var a=document.createElement('a');a.href="https://www.temablogger.com/";a.textContent='Tema Blogger';
  var y=el.querySelector('#year');if(y)y.textContent=year;
  el.replaceChildren(document.createTextNode('© '),y||document.createTextNode(year),document.createTextNode(' '),a,document.createTextNode('. All rights reserved.'));
 }
 function mirror(){
  if(!cfg.source)return;
  var src=document.querySelector(cfg.source);if(!src)return;
  var img=src.querySelector('img'),title=document.getElementById('tb-identity-blog-title');
  var name=cfg.native?tidy(title&&title.textContent):tidy(src.textContent);
  if(img)name=img.getAttribute('alt')||tidy(title&&title.textContent);
  if(!name)name=tidy(title&&title.textContent);
  document.querySelectorAll(cfg.mirror).forEach(function(target){
   if(target===src||src.contains(target))return;
   if(img&&img.getAttribute('src')){
    var old=target.querySelector('img');if(old&&old.getAttribute('src')===img.getAttribute('src'))return;
    var copy=img.cloneNode(true);copy.removeAttribute('id');copy.removeAttribute('width');copy.removeAttribute('height');
    target.replaceChildren(copy);
   }else if(name&&tidy(target.textContent)!==name)target.textContent=name;
  });
 }
 function apply(){queued=false;if(!document.body||document.body.id==='layout')return;
  if(cfg.creditTargets)document.querySelectorAll(cfg.creditTargets).forEach(stockCredit);
  mirror();
 }
 function schedule(){if(queued)return;queued=true;(window.requestAnimationFrame||function(f){setTimeout(f,0);})(apply);}
 function start(){apply();if(window.MutationObserver&&document.body)new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
//
